import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { cache } from 'react'
import { BackButton } from '@/components/BackButton'
import type { Comment, Post } from '@/lib/types'

interface BlogPostPageProps {
  /** Route params are async in the App Router and must be awaited. */
  params: Promise<{ id: string }>
}

/** Replaces `getStaticProps`' `revalidate: 300` — ISR every 5 minutes. */
export const revalidate = 300

/**
 * Replaces `fallback: 'blocking'`: params not returned by `generateStaticParams`
 * are rendered on demand on first request (this is the default, stated here for
 * clarity — set it to `false` for `fallback: false` behaviour).
 */
export const dynamicParams = true

/** Replaces `getStaticPaths`. */
export async function generateStaticParams(): Promise<{ id: string }[]> {
  const response = await fetch('https://jsonplaceholder.typicode.com/posts')
  const posts = (await response.json()) as Post[]

  return posts.slice(0, 10).map((post) => ({ id: post.id.toString() }))
}

/**
 * `cache` dedupes this across `generateMetadata` and the page component, so the
 * data is only fetched once per render.
 */
const getPostWithComments = cache(
  async (
    id: string
  ): Promise<{ post: Post; comments: Comment[] } | null> => {
    try {
      const [postResponse, commentsResponse] = await Promise.all([
        fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
          next: { revalidate: 300 },
        }),
        fetch(`https://jsonplaceholder.typicode.com/posts/${id}/comments`, {
          next: { revalidate: 300 },
        }),
      ])

      if (!postResponse.ok || !commentsResponse.ok) {
        return null
      }

      const [post, comments] = (await Promise.all([
        postResponse.json(),
        commentsResponse.json(),
      ])) as [Post, Comment[]]

      if (!post?.id) {
        return null
      }

      return { post, comments }
    } catch {
      return null
    }
  }
)

/** Replaces the per-page `<Head>` from the Pages Router. */
export async function generateMetadata({
  params,
}: BlogPostPageProps): Promise<Metadata> {
  const { id } = await params
  const data = await getPostWithComments(id)

  if (!data) {
    return { title: 'Post Not Found - My Blog' }
  }

  const description = data.post.body.substring(0, 160)

  return {
    title: `${data.post.title} - My Blog`,
    description,
    openGraph: {
      title: data.post.title,
      description,
    },
  }
}

export default async function BlogPostPage({ params }: BlogPostPageProps) {
  const { id } = await params
  const data = await getPostWithComments(id)

  // Replaces `return { notFound: true }` from `getStaticProps`.
  if (!data) {
    notFound()
  }

  const { post, comments } = data

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

