/**
 * Replaces `pages/_error.js`. The App Router splits that single page in two:
 * 404s are handled by `not-found.tsx`, and thrown errors by this error boundary.
 * There is no `statusCode`/`getInitialProps` here — the boundary receives the
 * error itself plus a `reset` function to retry rendering the segment.
 */
export default function Error({
  error,
  reset,
}: {
  error: Error & { digest?: string }
  reset: () => void
}) {
  return (
    <div className="error-page">
      <h1>An error occurred</h1>
      <p>Sorry, something went wrong.</p>
      {error.digest ? <p>Error digest: {error.digest}</p> : null}
      <button type="button" onClick={() => reset()}>
        Try Again
      </button>
    </div>
  )
}

